print('- difference:', a - b, a.difference(b))
# - difference: {1} {1}
print('^ symmetric_difference:', a ^ b, a.symmetric_difference(b))
# ^ symmetric_difference: {1, 4} {1, 4}

print('method accepts list:', a.union([9]), a.intersection([2]))
# method accepts list: {1, 2, 3, 9} {2}

